          "source": "初始文本",
          "text": "> 按原文件保留其题解、注释和赏析；组诗条目整体保留。\n\n沁园春·长沙\n\n一九二五年\n\n独立寒秋,\n湘江北去,\n橘子洲头。\n看万山红遍,\n层林尽染；\n漫江碧透，\n百舸争流。\n鹰击长空，\n鱼翔浅底，\n万类霜天竞自由。\n怅寥廓，\n问苍茫大地，\n谁主沉浮？  携来百侣曾游，\n忆往昔峥嵘岁月稠。\n恰同学少年，\n风华正茂；\n书生意气，\n挥斥方遒。\n指点江山，\n激扬文字，\n粪土当年万户侯。\n曾记否，\n到中流击水，\n浪遏飞舟？\n\n[题解]\n1925年1月，毛泽东回到湖南，组织了农民协会前身—雪耻会；是年冬天，反动势力有意逮捕；毛泽东南下广州，主持农民运动讲习所。这首词作于离开长沙前夕。\n\n[注释]\n（1）寒秋:深秋,晚秋。\n（2）橘子洲:长沙城西湘江中一沙洲。\n（3）舸：船。\n（4）万类：指一切生物。\n（5）霜天：秋天。\n（6）百侣：形容伴侣之多。\n（7）恰：正当，刚好。\n（8）挥斥：奔放。\n（9）遒：尽头。\n（10）激扬：激浊扬清。\n（11）万户侯：个人的功名富贵。\n（12）中流：水流之中。"
