      "id": "03",
      "title": "菩萨蛮·黄鹤楼",
      "form": "菩萨蛮",
      "subject": "黄鹤楼",
      "collection": "正编",
      "date": "1927年春",
      "year": 1927,
      "body": [
        "茫茫九派流中国,",
        "沉沉一线穿南北。",
        "烟雨莽苍苍，",
        "龟蛇锁大江。",
        "黄鹤知何去？",
        "剩有游人处。",
        "把酒酹滔滔，",
        "心潮逐浪高。"
      ],
      "preface": "",
      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：03（正编第 3 项）\n- 原文件标题：菩萨蛮·黄鹤楼\n- 原文件所标时间：一九二七年春\n\n本文按用户提供的文本整理，保留原文用字和时间；可能含异文或讹误，未逐字校勘。"
        },
        {
          "kind": "题解",
          "source": "初始文本",
          "text": "1927年春，正处第一次国内革命战争期间“四·一二”事变前夕；党内由于陈独秀执行右倾机会主义错误路线，给革命带来严重危机。在此背景下，毛泽东登临黄鹤楼，酒后面对滔滔江水，心潮起伏，写下此篇。"
        },
        {
          "kind": "注释",
          "source": "初始文本",
          "text": "（1）九派：九江；相传长江在湖北江西一带分为九个支派。\n（2）沉沉：深远的样子。\n（3）一线：通认为指今京广铁路。\n（4）龟蛇：龟山和蛇山。\n（5）酹：以酒祭地。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "〔黄鹤楼〕旧址在湖北省武昌市区之西长江岸边的黄鹤矶(一作黄鹄矶)上，即今武汉长江大桥南端西侧。楼在历史上曾几经毁坏修复，一九五五年修建大桥时拆去遗留建筑物，一九八五年六月在重新扩建后开放。《南齐书·州郡志》说有个叫子安的仙人，曾骑黄鹄(即鹤，古“鹄”、“鹤”二字通)经过黄鹄矶。《太平寰宇记》说骑鹤仙人叫费文袆(huī灰)，一作费祎(yī衣)，每乘黄鹤到此楼休息。楼因此得名。许多文人曾题诗抒慨，唐崔颢的名句“黄鹤一去不复返”，尤为历代传诵。作者借这个题目，抒发了革命家的截然不同的感慨。\n\n〔九派〕派，水的支流。相传在长江中游一带有九条支流同长江汇合，所以称“九派”。鲍照《登黄鹤矶》诗：“九派引沧流。”\n\n〔中国〕指中国的中部地区。\n\n〔一线〕指当时长江以南的粤汉铁路和以北的京汉铁路。一九五七年武汉长江大桥建成，两条铁路已接通，改名京广铁路。\n\n〔龟蛇锁大江〕龟蛇指龟山和蛇山，蛇山在武昌城西长江边，龟山在它对岸的汉阳，隔江对峙，好像要把长江锁住一样。\n\n〔把酒酹(lèi泪)滔滔〕酹是古代用酒浇在地上祭奠鬼神或对自然界事物设誓的一种习俗。这里是对滔滔的长江表示同反动势力斗争到底的决心。\n\n〔心潮〕作者自注：“一九二七年，大革命失败的前夕，心情苍凉，一时不知如何是好，这是那年的春季。夏季，八月七号，党的紧急会议，决定武装反击，从此找到了出路。”"
        },
        {
          "kind": "题解",
          "source": "品读版",
          "text": "一九二七年四月十一日，国民党军队缴了上海工人纠察队的枪，次日，又向罢工示威的工人开枪。在长沙，五月二十一日，何键、许克详开始捕杀共产党员，中共湖南省委退让，取消了十万农军进攻长沙的计划。毛泽东当时在武汉办农民运动讲习所。在四月二十七日的中共五大上，毛提出的“迅速加强土地斗争”的建议未能得到讨论。毛泽东准备应付突然事变，把妻子和三个孩子送回了湖南。二七年七月十五日，汪精卫在武汉宣布“清党”，国共两党彻底分裂。"
        }
      ],
