      "id": "06",
      "title": "采桑子·重阳",
      "form": "采桑子",
      "subject": "重阳",
      "collection": "正编",
      "date": "1929年10月",
      "year": 1929,
      "body": [
        "人生易老天难老,",
        "岁岁重阳。",
        "今又重阳，",
        "战地黄花分外香。",
        "一年一度秋风劲，",
        "不似春光。",
        "胜似春光，",
        "寥廓江天万里霜。"
      ],
      "preface": "",
