          "text": "- 出版社目录编号：06（正编第 6 项）\n- 原文件标题：采桑子·重阳\n- 原文件所标时间：一九二九年十月\n\n本文按用户提供的文本整理，保留原文用字和时间；可能含异文或讹误，未逐字校勘。"
