          "text": "- 出版社目录编号：07（正编第 7 项）\n- 原文件标题：如梦令·元旦\n- 原文件所标时间：一九三零年冬\n- 校勘时间：1930 年 1 月；据下引文章转述《毛泽东年谱》，作于 1 月 30 日（农历正月初一）。\n\n日期依据[《解放军报》转载研究文章](http://theory.people.com.cn/BIG5/n1/2021/0726/c40531-32169934.html)；正文未逐字校勘，下方保留两份原文。"
