          "text": "- 出版社目录编号：17（正编第 17 项）\n- 原文件标题：念奴娇·昆仑\n- 原文件所标时间：一九三五年十月\n\n阅读正文的“寒彻”据[中共中央党史和文献研究院网站转载讲座](https://www.dswxyjy.org.cn/BIG5/n1/2020/1109/c423725-31923949.html)校订；其余文字未逐字校勘，下方保留两份原文。"
