          "text": "- 出版社目录编号：20（正编第 20 项）\n- 原文件标题：人民解放军占领南京\n- 原文件所标时间：一九四九年四月\n\n阅读正文的“苍黄”据[《人民日报海外版》引文](https://paper.people.com.cn/hwbwap/html/2021-09/01/content_3066184.htm)校订；[人民网研究文章](http://theory.people.com.cn/n1/2021/0727/c40531-32171877.html)还记有抄件中“苍皇”改为“苍黄”的过程。下方保留两份原文，其余文字未逐字校勘。"
