          "text": "- 出版社目录编号：21（正编第 21 项）\n- 原文件标题：和柳亚子先生\n- 原文件所标时间：一九四九年四月二十九日\n\n阅读正文的“渝州”“防肠断”据[人民网文章](http://dangshi.people.com.cn/n1/2020/0615/c85037-31746414.html)核对；原始题解对所和原诗有自相矛盾之处，暂予保留。其余文字未逐字校勘。"
