          "kind": "题解",
          "source": "初始文本",
          "text": "柳亚子∶名弃疾，字安如，号亚子。第一次与毛泽东交往在一九二五年至二六年。一九四九年三月二十八夜柳亚子作《感事呈毛主席一首》：“开天辟地君真健，说项依刘我大雄。夺席谈经非五鹿，无车弹铗怨冯灌。头颅早悔平生贱，肝胆宁存一寸丹！安得南征驰捷报，分湖便是子陵滩。”\n分湖为柳亚子家乡，意为他要回家隐居。毛泽东和的是另一首诗。"
