          "text": "- 出版社目录编号：22（正编第 22 项）\n- 原文件标题：浣溪沙·和柳亚子先生\n- 原文件所标时间：一九五零年十月\n\n阅读正文的“百年魔怪”“不团圆”据[《人民周刊》引文](https://paper.people.com.cn/rmzk/html/2021-06/27/content_3056081.htm)校订。诗前小序据品读版补入；初始版完整条目的题解也有相同文字。下方保留两份原文。"
