      "id": "24",
      "title": "水调歌头·游泳",
      "form": "水调歌头",
      "subject": "游泳",
      "collection": "正编",
      "date": "1956年6月",
      "year": 1956,
      "body": [
        "才饮长沙水,",
        "又食武昌鱼。",
        "万里长江横渡，",
        "极目楚天舒。",
        "不管风吹浪打，",
        "胜似闲庭信步,",
        "今日得宽余。",
        "子在川上曰：",
        "逝者如斯夫！",
        "风樯动，龟蛇静，",
        "起宏图。",
        "一桥飞架南北，",
        "天堑变通途。",
        "更立西江石壁，",
        "截断巫山云雨，",
        "高峡出平湖。",
        "神女应无恙，",
        "当惊世界殊。"
      ],
      "preface": "",
      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：24（正编第 24 项）\n- 原文件标题：水调歌头·游泳\n- 原文件所标时间：一九五六年六月\n\n阅读正文按《人民日报》2021 年刊载的版本校订差异；下方保留两份用户原始文本。其余文字未逐字校勘。\n\n来源：[人民日报《展宏图 惊世界》](https://paper.people.com.cn/rmrbwap/html/2021-08/07/nw.D110000renmrb_20210807_2-05.htm)。"
        },
        {
          "kind": "题解",
          "source": "初始文本",
          "text": "1956年5月，毛泽东视察湖南后，又到武昌视察，在武汉江面游泳三次；这首词是第一次游过长江之后所写，热情歌颂了武汉长江大桥与三峡水利工程的建设。"
        },
        {
          "kind": "注释",
          "source": "初始文本",
          "text": "（1）极目：纵目、放眼。\n（2）舒：舒展、宽阔。\n（3）宽余：空闲。\n（4）逝者如斯乎：时光如这滔滔东去的江水。\n（5）樯：桅杆。\n（6）西江：西部的长江。\n（7）石壁：在三峡修筑一道拦水大坝。\n（8）巫山云雨：出自《文选》卷十九宋玉《高唐赋》。\n（9）神女：巫山之神。\n（10）应：料想。\n（11）当：准会。\n（12）殊：改变、不同。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "〔游泳〕一九五六年六月，作者曾由武昌游泳横渡长江，到达汉口。\n\n〔长沙水〕作者自注：“民谣：常德德山山有德，长沙沙水水无沙。所谓无沙水，地在长沙城东，有一个有名的‘白沙井’。”\n\n〔武昌鱼〕据《三国志·吴书·陆凯传》记载：吴主孙皓要把都城从建业(故城在今南京市南)迁到武昌，老百姓不愿意，有童谣说：“宁饮建业水，不食武昌鱼。”这里化用。武昌鱼，指古武昌(今鄂城)樊口的鳊(biān编)鱼，称团头鳊或团头鲂。\n\n〔极目楚天舒〕极目，放眼远望。武昌一带在春秋战国时属于楚国的范围，所以作者把这一带的天空叫“楚天”。舒，舒展，开阔。柳永词《雨霖铃》：“暮霭沉沉楚天阔”。作者在一九五七年二月十一日给黄炎培的信中说：“游长江二小时飘三十多里才达彼岸，可见水流之急。都是仰游侧游，故用‘极目楚天舒’为宜。”\n\n〔宽馀〕指神态舒缓，心情畅快。\n\n〔子在川上曰：逝者如斯夫〕《论语·子罕》：“子在川上，曰：‘逝者如斯夫!不舍昼夜。’”(孔子在河边，说道：“奔流而去的是这样匆忙啊!白天黑夜地不停留。”)\n\n〔风樯(qiáng墙)〕樯，桅杆。风樯，指帆船。\n\n〔龟蛇〕见《菩萨蛮·黄鹤楼》〔龟蛇锁大江〕注。\n\n〔一桥飞架南北〕指当时正在修建的武汉长江大桥。一九五八年版《毛主席诗词十九首》和一九六三年版《毛主席诗词》，作者曾将此句改为“一桥飞架，南北天堑变通途”，后经作者同意恢复原句。\n\n〔天堑(qiàn欠)〕堑，沟壕。古人把长江视为“天堑”。据《南史·孔范传》记载，隋伐陈，孔范向陈后主说：“长江天堑，古来限隔，虏军岂能飞渡？”\n\n〔更立西江石壁……当惊世界殊〕将来还打算在鄂西川东长江三峡一带建立巨型水坝(“西江石壁”)蓄水发电，水坝上游原来高峡间狭窄汹涌的江面将变为平静的大湖。到那时，巫山的雨水也都得流入这个“平湖”里来。巫山上的神女当然会健在如故，她看到这种意外的景象，该惊叹世界真是大变样了。巫山，在四川省巫山县东南。巫山形成的峡谷巫峡和上游的瞿塘峡、下游的西陵峡合称三峡。巫山云雨，传楚宋玉《高唐赋·序》说，楚怀王在游云梦泽的高唐时曾梦与巫山神女遇，神女自称“旦为朝云，暮为行雨”，这里只是借用这个故事中的字面和人物。"
        },
        {
          "kind": "题解",
          "source": "品读版",
          "text": "一九五六年六月一日，毛泽东从武昌游过长江到达汉口。六月三日，第二次游过长江，从汉阳穿过长江大桥桥洞到武昌。四日，第三次游过长江，也是从汉阳到武昌。"
        }
      ],
