          "text": "> 按原文件保留其题解、注释和赏析；组诗条目整体保留。\n\n水调歌头·游泳\n\n一九五六年六月\n\n才饮长沙水,\n又食武昌鱼。\n万里长江横渡，\n极目楚天舒。\n不管风吹雨打，\n胜似闲庭信步,\n今日得宽余。\n子在川上曰：\n逝者如斯乎！  风樯动，龟蛇静，\n起宏图。\n一桥飞架南北，\n天堑变通途。\n更立西江石壁，\n截断巫山云雨，\n高峡出平湖。\n神女应无恙，\n当惊世界殊。\n\n[题解]\n1956年5月，毛泽东视察湖南后，又到武昌视察，在武汉江面游泳三次；这首词是第一次游过长江之后所写，热情歌颂了武汉长江大桥与三峡水利工程的建设。\n\n[注释]\n（1）极目：纵目、放眼。\n（2）舒：舒展、宽阔。\n（3）宽余：空闲。\n（4）逝者如斯乎：时光如这滔滔东去的江水。\n（5）樯：桅杆。\n（6）西江：西部的长江。\n（7）石壁：在三峡修筑一道拦水大坝。\n（8）巫山云雨：出自《文选》卷十九宋玉《高唐赋》。\n（9）神女：巫山之神。\n（10）应：料想。\n（11）当：准会。\n（12）殊：改变、不同。"
