          "source": "初始文本",
          "text": "> 按原文件保留其题解、注释和赏析；组诗条目整体保留。\n\n答友人\n\n一九六一年\n\n九嶷山上白云飞，  洞庭破涌连天雪，\n帝子乘风下翠微。  长岛人歌动地诗。\n斑竹一枝千滴泪，  我欲因之梦廖廓，\n红霞万朵百重衣。  芙蓉国里尽朝晖。\n\n[题解]\n这首诗背景不详，但诗中所写均为湖南故实。可能是写给一位多年不见面的住在长沙的女友人。\n\n[注释]\n1）翠微：谓青缥色的山气。\n（2）斑竹：湘妃竹。\n（3）长岛：指湘江中的水露洲或橘子洲。\n（4）芙蓉国：湖南的代称。\n（5）尽朝晖：到处从满生气。\n\n[赏析]\n诗中使用古代神话传说，描写故国山水风光。以柔和的色调与舒缓的抒情，通过幻想创造了一幅优美的图像。全诗以革命现实主义与革命浪漫主义相结合，通过描写友人的身世与遭遇，赞美友人的高贵品质。诗中使用古代神话传说，描写故国山水风光。以柔和的色调与舒缓的抒情，通过幻想创造了一幅优美的图像。全诗以革命现实主义与革命浪漫主义相结合，通过描写友人的身世与遭遇，赞美友人的高贵品质。诗中使用古代神话传说，描写故国山水风光。以柔和的色调与舒缓的抒情，通过幻想创造了一幅优美的图像。全诗以革命现实主义与革命浪漫主义相结合，通过描写友人的身世与遭遇，赞美友人的高贵品质。"
