      "id": "32",
      "title": "七律·和郭沫若同志",
      "form": "七律",
      "subject": "和郭沫若同志",
      "collection": "正编",
      "date": "1961年11月17日",
      "year": 1961,
      "body": [
        "一从大地起风雷，",
        "便有精生白骨堆。",
        "僧是愚氓犹可训，",
        "妖为鬼蜮必成灾。",
        "金猴奋起千钧棒，",
        "玉宇澄清万里埃。",
        "今日欢呼孙大圣，",
        "只缘妖雾又重来。"
      ],
      "preface": "",
      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：32（正编第 32 项）\n- 原文件标题：和郭沫若同志\n- 原文件所标时间：一九六一年十一月十七日\n\n阅读正文的“奋起”据[人民网研究文章](http://theory.people.com.cn/n1/2024/1105/c40764-40354653.html)校订；其余文字未逐字校勘，下方保留两份原文。"
        },
        {
          "kind": "题解",
          "source": "初始文本",
          "text": "此诗和的是郭沫若的《看〈孙悟空三打白骨精〉》，作于中共与苏共分裂公开化之时；诗中对混淆是非的唐僧持偏激看法，隐语现实中某些人对国际政治舞台上的投降主义者的性质估计不足。"
        },
        {
          "kind": "注释",
          "source": "初始文本",
          "text": "（1）一从：自从；\n（2）僧：唐僧；\n（3）愚氓：愚民；\n（4）鬼蜮∶妖怪变成人叫鬼蜮；\n（5）玉宇：琼天玉宇；\n（6）埃：妖气；\n（7）妖雾：指机会主义者。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "〔和郭沫若同志〕一九六一年十月间，浙江省绍剧团在北京演出根据《西游记》第二十七回白骨精故事改编的绍剧《孙悟空三打白骨精》。郭沫若看过戏作了一首诗，借以反对当时所说的现代修正主义。本诗的主旨与郭诗相同(这也是作者此后大多数诗词的主题)，只是不同意郭诗敌视被白骨精欺骗的唐僧的看法。郭读本诗后表示接受作者的意见。郭沫若(一八九二——一九七八)，四川乐山人，现代著名的文学家和历史学家。两诗句中多用《西游记》故事，因为流传较广，现不加注。\n\n〔愚氓(méng萌)〕氓，古义通“民”。愚氓，愚蠢的人。\n\n〔鬼蜮(yù玉)〕蜮，古代传说中水里一种暗害人的怪物。鬼蜮，即鬼怪，后来比喻阴险作恶的人。"
        },
        {
          "kind": "题解",
          "source": "品读版",
          "text": "白骨精的故事，见《西游记》第二十七回，“尸魔三戏唐三藏，圣僧恨逐美猴王”。这里讲的是绍剧（绍兴大板）改动过的情节，孙悟空在被逐后扮作白骨精的母亲，诱使白骨精得意洋洋地在唐僧面前自己揭露自己三变三骗的经过，从而使唐僧幡然醒悟。"
        }
      ],
