      "body": [
        "风雨送春归,",
        "飞雪迎春到。",
        "已是悬崖百丈冰，",
        "犹有花枝俏。",
        "俏也不争春，",
        "只把春来报。",
        "待到山花烂漫时，",
        "她在丛中笑。"
      ],
      "preface": "读陆游咏梅词，反其意而用之。",
      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：33（正编第 33 项）\n- 原文件标题：卜算子·咏梅\n- 原文件所标时间：一九六一年十二月\n\n诗前说明据[中共中央党史和文献研究院网站转载讲座](https://www.dswxyjy.org.cn/BIG5/n1/2020/1109/c423725-31923949.html)和品读版补入。正文未逐字校勘，下方保留两份原文。"
        },
        {
          "kind": "题解",
          "source": "初始文本",
          "text": "1961年冬，正是反华叫嚣闹得正凶的时候，也是三年自然灾害困难的时候；毛泽东用梅花的形象和风格，鼓励大家敢于面对困难、战胜困难。"
        },
        {
          "kind": "注释",
          "source": "初始文本",
          "text": "（1）送春归：把春天送走。\n（2）烂漫：色彩鲜丽。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "陆游(1125—1210)　字务观，号放翁，山阴(今浙江绍兴)人。南宋爱国的大诗人。他生当封建统治阶级向外来侵略势力委曲求和的时代，爱国抱负不为时用，晚年退居家乡。他在《咏梅》词中表现出孤芳自赏、凄凉抑郁的调子。本词用陆游原调原题，但情调完全相反，所以说“反其意而用之”。\n\n卜算子：词牌名，骆宾王诗用数名，人称卜算子。山谷词“似扶著，卖卜算”，取卖卜算命的意思。\n\n风雨送春归：辛弃疾《摸鱼儿》，“更能消几番风雨，匆匆春又归去”。"
        }
      ],
