      "body": [
        "去去思君深，",
        "思君君不来。",
        "愁杀芳年友，",
        "悲叹有余哀。",
        "衡阳雁声彻，",
        "湘滨春溜回。",
        "感物念所欢，",
        "踯躅城南隈。",
        "城隈草萋萋，",
        "涔泪浸双题。",
        "采采余孤景，",
        "日落衡云西。",
        "方期沆瀁游，",
        "零落匪所思。",
        "永诀从今始，",
        "午夜惊鸣鸡。",
        "鸣鸡一声唱，",
        "汗漫东皋上。",
        "冉冉望君来，",
        "握手珠眶涨。",
        "关山蹇骥足，",
        "飞飙拂灵帐。",
        "我怀郁如焚，",
        "放歌倚列嶂。",
        "列嶂青且蒨，",
        "愿言试长剑。",
        "东海有岛夷，",
        "北山尽仇怨。",
        "荡涤谁氏子，",
        "安得辞浮贱。",
        "子期竟早亡，",
        "牙琴从此绝。",
        "琴绝最伤情，",
        "朱华春不荣。",
        "后来有千里，",
        "谁与共平生。",
        "望灵荐杯酒，",
        "惨淡看铭旌。",
        "惆怅中何寄？",
        "江天水一泓。"
      ],
