          "text": "> 按原文件保留其题解、注释和赏析；组诗条目整体保留。\n\n送纵宇一郎东行\n\n约一九一六年\n\n云开衡岳积阴止，\n天马凤凰春树里。\n年少峥嵘屈贾才，\n山川奇气曾钟此。\n君行吾为发浩歌，\n鲲鹏击浪从兹始。\n洞庭湘水涨连天，\n艟艨巨舰直东指。\n无端散出一天愁，\n幸被东风吹万里。\n丈夫何事足萦怀，\n要将宇宙看稊米。\n沧海横流安足虑，\n世事纷纭从君理。\n管却自家身与心，\n胸中日月常新美。\n名世于今五百年，\n诸公碌碌皆余子。\n平浪宫前友谊多，\n崇明对马衣带水。\n东瀛濯剑有书还，\n我返自崖君去矣。"
