      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：45（副编第 6 项）\n- 原文件标题：临江仙·给丁玲同志\n- 原文件所标时间：一九三六年二月\n\n本文按用户提供的文本整理，保留原文用字和时间；可能含异文或讹误，未逐字校勘。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "〔给丁玲同志〕一九三六年夏，著名左翼女作家丁玲逃离被国民党囚禁三年多的南京，秘密经上海、北平、西安于十一月来到陕北保安。中共中央宣传部在一孔大窑洞里开会欢迎她，中央领导人毛泽东、张闻天、周恩来等都出席。会后，毛泽东问丁玲打算做什么，她答“当红军”。她随后就到前方总政治部工作。作者因此写这首词送她。丁玲(一九○四——一九八六)，原名蒋冰之，湖南临澧人。一九三二年参加中国共产党。\n\n〔保安〕在陕西省西北部，当时是中共中央所在地，一九三六年改名志丹县。\n\n〔纤笔〕细致描绘的笔，指丁玲的文笔。\n\n〔毛瑟〕德国毛瑟工厂所制造的步枪和手枪。孙中山在一九二二年八月二十四日《与报界的谈话》中说：“常言谓：一枝笔胜于三千毛瑟枪。”\n\n〔陇山〕在陕西省陇县西北，延伸于陕甘边境。"
        }
      ],
