      "collection": "副编",
      "date": "1955年",
      "year": 1955,
      "body": [
        "春江浩荡暂徘徊，",
        "又踏层峰望眼开。",
        "风起绿洲吹浪去，",
        "雨从青野上山来。",
        "尊前谈笑人依旧，",
        "域外鸡虫事可哀。",
        "莫叹韶华容易逝，",
        "卅年仍到赫曦台。"
      ],
      "preface": "",
      "notes": [
        {
          "kind": "编者说明",
          "source": "整理说明",
          "text": "- 出版社目录编号：50（副编第 11 项）\n- 原文件标题：和周世钊同志\n- 原文件所标时间：一九五五年\n\n本文按用户提供的文本整理，保留原文用字和时间；可能含异文或讹误，未逐字校勘。"
        },
        {
          "kind": "注释",
          "source": "品读版",
          "text": "〔周世钊〕见《七律·答友人》〔答友人〕注。周当时任湖南省教育厅副厅长兼湖南省立第一师范学校校长。\n\n〔尊前〕尊同“樽”，酒杯。尊前，酒席前。\n\n〔域外鸡虫事可哀〕国际间的某些事件像鸡虫得失一样渺小，人们为这些小事而勾心斗角是可悲的。这里所指的具体内容待考。唐杜甫《缚鸡行》：“小奴缚鸡向市卖，鸡被缚急相喧争。家中厌鸡食虫蚁，不知鸡卖还遭烹。虫鸡于人何厚薄？吾叱奴人解其缚。鸡虫得失无了时，注目寒江倚山阁。”\n\n〔韶华〕美好的年华，指人的青年时代。\n\n〔赫曦(xī西)台〕在湖南省长沙市岳麓山岳麓书院。朱熹曾称岳麓山顶为赫曦，后因称山上的台为赫曦台。清代因山上的台已毁，将原“赫曦台”匾额悬于岳麓书院“前台”，由此前台更名赫曦台。赫曦，光明盛大的样子。"
        }
      ],
