          "source": "初始文本",
          "text": "1）杀人刀：指屈原作《离骚》所发挥的战斗作用。\n（2）艾萧：艾蒿、臭草，比喻奸佞小人。\n（3）椒兰：申椒和兰草，比喻贤德之士。\n（4）冲向万里涛：指屈原投汨罗江而死。"
