      "form": "杂言诗",
      "subject": "八连颂",
      "collection": "副编",
      "date": "1963年8月1日",
      "year": 1963,
      "body": [
        "好八连，天下传。",
        "为什么？意志坚。",
        "为人民，几十年。",
        "拒腐蚀，永不沾。",
        "因此叫，好八连。",
        "解放军，要学习。",
        "全军民，要自立。",
        "不怕压，不怕迫。",
        "不怕刀，不怕戟。",
        "不怕鬼，不怕魅。",
        "不怕帝，不怕贼。",
        "奇儿女，如松柏。",
        "上参天，傲霜雪。",
        "纪律好，如坚壁。",
        "军事好，如霹雳。",
        "政治好，称第一。",
        "思想好，能分析。",
        "分析好，大有益。",
        "益在哪？团结力。",
        "军民团结如一人，",
        "试看天下谁能敌。"
      ],
      "preface": "",
