      "form": "七古",
      "subject": "七古（1973年7月）",
      "collection": "补编",
      "date": "1973年7月",
      "year": 1973,
      "body": [
        "君不见高阳酒徒起草中，",
        "长揖山东隆准公。",
        "入门不拜骋雄辩，",
        "两女辍洗来趋风。",
        "东下齐城七十二，",
        "指挥楚汉如旋蓬。",
        "不料韩信不听话，",
        "十万大军下历城。",
        "齐王火冒三千丈，",
        "抓了酒徒付鼎烹。"
      ],
      "preface": "",
