      "collection": "补编",
      "date": "未标明",
      "year": null,
      "body": [
        "曾经秋肃临天下，",
        "敢遣春温上笔端。",
        "尘海苍茫沉百感，",
        "金风萧瑟走千官。",
        "喜攀飞翼通身暖，",
        "若坠空云半截寒。",
        "竦听荒鸡偏阒寂，",
        "起看星斗正阑干。"
      ],
